// Element defaults stay local to the landing composition.
export const tourSkin = Object.fromEntries(
  Object.entries(styles).map(([key, style]) => [
    key,
    [
      className(reset.button, reset.text, reset.link, reset.list, style),
      key === 'studioRoot'
        ? 'landing-studio'
        : key === 'studioPreview'
          ? 'create-board-theme'
          : '',
    ]
      .filter(Boolean)
      .join(' '),
  ]),
) as Record<keyof typeof styles, string>
